use super::*;
use futures_util::future::BoxFuture;
use crate::resources::ResourceBudget;
use std::os::unix::fs::PermissionsExt;
struct DisabledNative;
impl NotificationAdapter for DisabledNative {
    fn permission<'a>(&'a self,_request:bool,_cancel:&'a CancellationToken)->BoxFuture<'a,Result<NotificationPermission>>{Box::pin(async{Err(Error::new("TEST_UNEXPECTED_NATIVE","disabled notifications must not invoke native permission"))})}
    fn submit<'a>(&'a self,_message:NotificationMessage,_cancel:&'a CancellationToken)->BoxFuture<'a,Result<NativeDelivery>>{Box::pin(async{Err(Error::new("TEST_UNEXPECTED_NATIVE","disabled notifications must not submit"))})}
    fn settle<'a>(&'a self,_id:&'a str,_cancel:&'a CancellationToken)->BoxFuture<'a,Result<NativeDelivery>>{Box::pin(async{Err(Error::new("TEST_UNEXPECTED_NATIVE","disabled notifications must not settle"))})}
    fn remove<'a>(&'a self,_id:&'a str)->BoxFuture<'a,Result<NativeRemoval>>{Box::pin(async{Err(Error::new("TEST_UNEXPECTED_NATIVE","disabled notifications must not remove"))})}
    fn drain(&self)->BoxFuture<'_,Result<NativeDrain>>{Box::pin(async{Err(Error::new("TEST_UNEXPECTED_NATIVE","disabled notifications must not drain"))})}
}
struct Fixture{dir:tempfile::TempDir,io:BoundedIo,service:EventService}
fn fixture()->Fixture {
    let executable=std::env::var_os("OC_DATA_WORKER_TEST_EXECUTABLE").expect("build worker and set OC_DATA_WORKER_TEST_EXECUTABLE");
    let dir=tempfile::Builder::new().permissions(std::fs::Permissions::from_mode(0o700)).tempdir().unwrap();let home=dir.path().to_owned();let io=BoundedIo::new(ResourceBudget::default());let worker=DataWorker::new(io.clone(),PathBuf::from(executable));
    let paths=EventPaths{home:home.clone(),profile:home.clone(),database:home.join("events.sqlite"),hermes_database:home.join("hermes.sqlite"),journal:home.join("notifications.json")};
    let service=EventService::new(io.clone(),worker,paths,Arc::new(DisabledNative),ResolvedLanguage::English,EventCallbacks{notification_changed:Arc::new(|state|assert!(matches!(state.phase,NotificationPhase::Off|NotificationPhase::EventsDisabled))),task_name:Arc::new(|_|panic!("names were not opted in"))}).unwrap();Fixture{dir,io,service}
}
fn input(at:&str,state:SourceState)->EventInput{let mut snapshot=MonitorSnapshot::default();let mut source=SourceStatus::new("agent-socket","Socket",state,"metadata");source.last_attempt_at=Some(at.into());snapshot.agents.data=Some(AgentSnapshot{collected_at:at.into(),agents:vec![],active_subagent_count:Some(0),sources:vec![source]});EventInput{snapshot,enabled:SectionEnabled{agents:true,schedules:false,system:true}}}
#[tokio::test]async fn event_service_collects_every_section_and_persists_outage_recovery(){let f=fixture();let service=&f.service;service.start().await.unwrap();let now=chrono::Utc::now();let before=(now-chrono::Duration::seconds(70)).to_rfc3339_opts(chrono::SecondsFormat::Millis,true);let now=now.to_rfc3339_opts(chrono::SecondsFormat::Millis,true);let cancel=CancellationToken::new();let first=service.collect(input(&before,SourceState::Error),&cancel).await.unwrap();assert_eq!(first.retention.count,0);let second=service.collect(input(&now,SourceState::Error),&cancel).await.unwrap();assert_eq!(second.retention.count,1);let duplicate=service.collect(input(&now,SourceState::Error),&cancel).await.unwrap();assert_eq!(duplicate.retention.count,1);service.stop().await.unwrap();service.start().await.unwrap();service.collect(input(&now,SourceState::Ok),&cancel).await.unwrap();let page=service.query(EventQuery::default(),&cancel).await.unwrap();assert_eq!(page.entries.len(),2);assert_eq!(page.entries[0].event_type,LocalEventType::SourceRecovered);assert_eq!(page.entries[1].event_type,LocalEventType::SourceUnavailable);service.disable().await.unwrap();assert_eq!(service.query(EventQuery::default(),&cancel).await.unwrap_err().code,"OC_EVENTS_DISABLED");assert!(!f.dir.path().join("notifications.json").exists());f.io.shutdown().await.unwrap();}
#[tokio::test]async fn event_service_preserves_upstream_failure_and_does_not_forge_events(){let f=fixture();f.service.start().await.unwrap();let mut data=input(&timestamp(),SourceState::Unsupported);data.enabled.schedules=true;let snapshot=f.service.collect(data,&CancellationToken::new()).await.unwrap();assert_eq!(snapshot.retention.count,0);assert!(snapshot.sources.iter().any(|s|s.id=="hermes-events"&&s.state==SourceState::Error));assert!(snapshot.coverage.iter().any(|c|c.source_id=="hermes-events"&&c.state==CoverageState::Unavailable));assert!(snapshot.coverage.iter().find(|c|c.source_id=="hermes-events").unwrap().last_gap.is_some());f.service.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn event_service_coalesces_concurrent_collection_and_restarts_after_drain(){let f=fixture();f.service.start().await.unwrap();let data=input(&timestamp(),SourceState::Ok);let mut requests=vec![];for _ in 0..8{let service=f.service.clone();let data=data.clone();requests.push(tokio::spawn(async move{service.collect(data,&CancellationToken::new()).await}));}let mut revisions=vec![];for request in requests{revisions.push(request.await.unwrap().unwrap().revision);}assert!(revisions.iter().all(|r|*r==revisions[0]));f.service.stop().await.unwrap();f.service.start().await.unwrap();f.service.collect(input(&timestamp(),SourceState::Ok),&CancellationToken::new()).await.unwrap();f.service.quit().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn event_service_query_cancel_drains_real_locked_worker(){let f=fixture();f.service.start().await.unwrap();f.service.collect(input(&timestamp(),SourceState::Ok),&CancellationToken::new()).await.unwrap();let db=rusqlite::Connection::open(f.dir.path().join("events.sqlite")).unwrap();db.execute_batch("BEGIN EXCLUSIVE").unwrap();let service=f.service.clone();let task=tokio::spawn(async move{service.query(EventQuery::default(),&CancellationToken::new()).await});tokio::time::sleep(std::time::Duration::from_millis(50)).await;f.service.cancel_query().await.unwrap();let error=task.await.unwrap().unwrap_err();assert!(error.is_cancelled(),"{error}");db.execute_batch("ROLLBACK").unwrap();db.close().unwrap();assert!(f.service.query(EventQuery::default(),&CancellationToken::new()).await.is_ok());f.service.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[test]fn observations_cover_collection_and_source_states_without_inventing_missing_samples(){let at=timestamp();let mut data=input(&at,SourceState::Partial);data.snapshot.agents.last_attempt_at=Some(at.clone());data.snapshot.agents.error=Some("failed".into());data.snapshot.schedules.last_attempt_at=Some(at.clone());data.snapshot.schedules.last_success_at=Some(at.clone());data.snapshot.system.last_attempt_at=Some(at.clone());let samples=observations(&data).unwrap();assert_eq!(samples.len(),4);assert!(samples.iter().any(|s|s.id=="collection:agents"&&s.state==SourceState::Error));assert!(samples.iter().any(|s|s.id=="agent-socket"&&s.state==SourceState::Partial));assert!(samples.iter().any(|s|s.id=="collection:schedules"&&s.state==SourceState::Disabled));assert!(samples.iter().any(|s|s.id=="collection:system"&&s.state==SourceState::Unsupported));}

#[tokio::test]async fn event_service_database_replacement_has_persistent_gap_and_recovers(){
    let f=fixture();f.service.start().await.unwrap();f.service.collect(input(&timestamp(),SourceState::Ok),&CancellationToken::new()).await.unwrap();
    std::fs::rename(f.dir.path().join("events.sqlite"),f.dir.path().join("old.sqlite")).unwrap();
    let replacement=f.service.collect(input(&timestamp(),SourceState::Ok),&CancellationToken::new()).await.unwrap();assert!(replacement.coverage.iter().any(|c|c.source_id=="event-store"&&c.code.as_deref()==Some("event-store-replaced")));assert_eq!(replacement.sources.iter().filter(|s|s.id=="event-store").count(),1);
    let recovered=f.service.collect(input(&timestamp(),SourceState::Ok),&CancellationToken::new()).await.unwrap();let coverage=recovered.coverage.iter().find(|c|c.source_id=="event-store").unwrap();assert_eq!(coverage.state,CoverageState::Observing);assert!(coverage.last_gap.is_some());f.service.stop().await.unwrap();f.io.shutdown().await.unwrap();
}
